import {mapState} from "vuex";
import {communityInfoApi, commentListApi, commentReplyApi, commentVerifyApi} from "@/api/community";

export default {
  name: "videoDetails",
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 110;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    }
  },
  data() {
    return {
      modals: false,
      activeName: 'detail',
      formValidate: {},
      tableFrom: {
        page: 1,
        limit: 15,
        community_id: 0
      },
      total: 0,
      tableList: [],
      tableData: [],
      columns: [
        {
          title: 'ID',
          key: 'id',
          width: 80
        },
        {
          title: "商品信息",
          slot: "info",
          minWidth: 340,
        },
        {
          title: "售价",
          key: "price",
          minWidth: 125,
        },
        {
          title: "库存",
          key: "stock",
          minWidth: 125,
        }
      ],
      columns2: [
        {
          title: 'ID',
          key: 'id',
          width: 80,
          tree: true
        },
        {
          title: "用户昵称",
          key: "author",
          minWidth: 150,
        },
        {
          title: "评价内容",
          key: "content",
          minWidth: 180,
        },
        {
          title: "回复数",
          key: "comment_num",
          width: 125,
        },
        {
          title: "点赞数",
          key: "like_num",
          minWidth: 125,
        },
        {
          title: "评论时间",
          key: "add_time",
          minWidth: 180,
        },
        {
          title: "上级评论",
          key: "comment_reply_content",
          minWidth: 200,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 120
        }
      ],
      replyForm:{
        page: 1,
        limit: 20,
        is_reply:1,
        community_id:''
      },
    };
  },
  created() {
  },
  methods: {
    //内容详情
    getInfo(id) {
      communityInfoApi(id).then(res => {
        this.formValidate = res.data;
        this.tableData = res.data.product;
        this.tableFrom.community_id = id;
        this.commentAllList();
      }).catch(err => {
        this.$Message.error(err.msg)
      })
    },
    commentAllList() {
      commentListApi(this.replyForm).then(res => {
        res.data.list.map(item=>{
          if(item.comment_num > 0){
            this.$set(item,'children',[]);
            this.$set(item,'_loading',false);
          }
        })
        let data = res.data;
        this.tableList = data.list;
        this.total = res.data.count;
      }).catch(err => {
        this.$Message.error(err.msg)
      })
    },
    handleLoadData(item, callback){
      item._loading = true;
      commentListApi({is_reply: 0,reply_id: item.id}).then(res => {
        item._loading = true;
        callback(res.data.list);
      })
    },
    // 回复
    reply(row) {
      this.$modalForm(commentReplyApi(row.id)).then(() => this.commentAllList());
    },
    // 审核
    verify(row) {
      this.$modalForm(commentVerifyApi(row.id)).then(() => this.commentAllList());
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/community/comment/del/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.tableList.splice(num, 1);
            if (!this.tableList.length) {
              this.tableFrom.page =
                  this.tableFrom.page == 1 ? 1 : this.tableFrom.page - 1;
            }
            this.commentAllList();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    pageChange(index) {
      this.tableFrom.page = index;
      this.commentAllList();
    }
  }
};
